{
 let art = std::path::Path::new("/Users/kevintruong/project/SpurCode/docs/research/artifacts/2026-11-15-rust-macro-qualification-fix");
 let input = art.join("control.rs"); let mir = art.join("control.mir"); let binary = art.join("control");
 let version = std::process::Command::new("rustc").env("RUSTUP_TOOLCHAIN","1.94.1").args(["--version","--verbose"]).output()?;
 assert!(version.status.success() && String::from_utf8_lossy(&version.stdout).starts_with("rustc 1.94.1"));
 let mut compiler = Vec::new();
 for args in [
  vec!["--edition=2021","--crate-name","macro_fix_control","--emit=mir",input.to_str().unwrap(),"-o",mir.to_str().unwrap()],
  vec!["--edition=2021","--crate-name","macro_fix_control",input.to_str().unwrap(),"-o",binary.to_str().unwrap()]
 ] {
  let r = std::process::Command::new("rustc").env("RUSTUP_TOOLCHAIN","1.94.1").args(&args).output()?;
  compiler.push(serde_json::json!({"args":args,"exit":r.status.code(),"stdout":String::from_utf8_lossy(&r.stdout),"stderr":String::from_utf8_lossy(&r.stderr)}));
  assert!(r.status.success(), "Compiler fixture failed");
 }
 let runtime = std::process::Command::new(&binary).output()?;
 assert!(runtime.status.success() && runtime.stdout == b"binding-control-ok\n");
 let mir_text = std::fs::read_to_string(&mir)?;
 let mixed = mir_text.split("fn observed_mixed_macro(").nth(1).unwrap().split("\nfn ").next().unwrap();
 assert!(mixed.contains("Vec::<u8>::new") && mixed.contains("LocalFactory::new") && mixed.contains("helper()"));
 std::fs::write(art.join("compiler.json"),serde_json::to_vec_pretty(&serde_json::json!({"version":String::from_utf8_lossy(&version.stdout),"commands":compiler,"runtime_exit":runtime.status.code(),"runtime_stdout":String::from_utf8_lossy(&runtime.stdout),"mixed_mir_targets_verified":["Vec::<u8>::new","LocalFactory::new","helper"],"source":"control.rs"}))?)?;
 let args = vec![art.join("validate_extension.py").to_str().unwrap().to_owned(),
 "--extension".to_owned(),"/Users/kevintruong/project/SpurCode/docs/research/artifacts/2026-11-15-duckdb-file-facts/integration/spur_graph.duckdb_extension".to_owned(),
 "--mode".to_owned(),"baseline".to_owned(),"--output".to_owned(),art.join("baseline.json").to_str().unwrap().to_owned()];
 let r = std::process::Command::new("/private/tmp/spur-graph-duckdb-v2-20261114/bin/python").args(&args).output()?;
 std::fs::write(art.join("baseline.stderr.txt"), &r.stderr)?;
 std::fs::write(art.join("baseline.stdout.txt"), &r.stdout)?;
 assert!(r.status.success(),"Baseline validation failed; inspect saved stderr");
 println!("{}",String::from_utf8_lossy(&r.stdout));
}
